// private dev source. Re-run emit-core.js whenever the PIXHIST-CORE region or _PIXHIST_KEY changes.
'use strict';
module.exports.v = "dtr_oe_pixhist_v9";
module.exports.body = "    //   Everything between the PIXHIST-CORE markers is the SINGLE SOURCE OF TRUTH for how a thumbnail becomes\r\n    //   colour-family fractions. It is SELF-CONTAINED (no DOM, no OE refs — just Math): the offline table\r\n    //   generator (tools/color-table/compute-table.js) literally extracts this region from bulk.js and runs it,\r\n    //   so the precomputed colour table can NEVER drift from the live engine. Change a knob here and re-run the\r\n    //   generator → the table matches automatically. Keep this block DOM-free; anything browser-specific (the\r\n    //   Image/canvas decode) lives OUTSIDE the markers in _pixHistCompute.\r\n    // ── CALIBRATION KNOBS (the whole game — each is ONE number, tune against real items) ────────────────────\r\n    //   WHITE = the \"very light anything\" the user means (light grey / silver / eggshell / faint tint of a hue).\r\n    //   Two cuts so it is generous without swallowing pale-but-clearly-coloured pixels: a light+low-sat cut,\r\n    //   plus a near-white catch that tolerates a touch more saturation once the pixel is VERY light.\r\n    const _PIX_WHITE_L = 0.75, _PIX_WHITE_S = 0.28;    // primary white: light AND not-very-saturated\r\n    const _PIX_WHITE_L2 = 0.88, _PIX_WHITE_S2 = 0.50;  // near-white: very light even if a bit more saturated\r\n    const _PIX_BLACK_L = 0.13;                         // solid black cut (after outline erosion)\r\n    const _PIX_GREY_S  = 0.14;                         // mid neutral (below white, above black)\r\n    const _PIX_DARK_L  = 0.22;                         // erosion: a near-black pixel is an OUTLINE candidate\r\n    const _PIX_HALO_PASSES = 2;                        // how many 1px rings of white/grey backdrop-blend halo to peel\r\n    const _PIX_BG_EXACT = 16;                          // enclosed-hole fill: drop pixels this close (Manhattan) to the flat backdrop colour anywhere\r\n    const _PIX_BGW_MIN  = 250;                         // flat-backdrop white: every channel >= this (near-pure #FFFFFF baked pet-hole)\r\n    const _PIX_BGW_FLAT = 2;                           // ...AND locally flat (max abs channel diff to a 4-neighbour <= this) → not shaded item white\r\n    // per-PIXEL family classifier for the pixel engine — kept SEPARATE from _oeHexFamily so the itemdb path and\r\n    // the item-page folded-colour display stay EXACTLY as deployed. Same hue bands as _oeHexFamily; only the\r\n    // neutral cluster is more generous (the white knobs above).\r\n    function _pixFamily(r, g, b) {\r\n      const rn = r / 255, gn = g / 255, bn = b / 255;\r\n      const mx = Math.max(rn, gn, bn), mn = Math.min(rn, gn, bn), dl = mx - mn, l = (mx + mn) / 2;\r\n      const s = dl === 0 ? 0 : dl / (1 - Math.abs(2 * l - 1));\r\n      if ((l >= _PIX_WHITE_L && s <= _PIX_WHITE_S) || (l >= _PIX_WHITE_L2 && s <= _PIX_WHITE_S2)) return 'white';\r\n      if (l <= _PIX_BLACK_L) return 'black';\r\n      if (s <= _PIX_GREY_S) return 'grey';\r\n      let h = 0;\r\n      if (dl) { if (mx === rn) h = 60 * (((gn - bn) / dl) % 6); else if (mx === gn) h = 60 * ((bn - rn) / dl + 2); else h = 60 * ((rn - gn) / dl + 4); if (h < 0) h += 360; }\r\n      if (h < 12 || h >= 345) return l >= .7 ? 'pink' : 'red';\r\n      if (h < 50) { if (l < .34) return 'brown'; if (s < .5 && l < .70) return 'brown'; return h < 42 ? 'orange' : 'yellow'; }\r\n      if (h < 66) { if (l < .42 || s < .35) return 'brown'; return 'yellow'; }\r\n      if (h < 160) return 'green';\r\n      if (h < 196) return 'aqua';\r\n      if (h < 254) return 'blue';\r\n      if (h < 300) return 'purple';\r\n      return 'pink';\r\n    }\r\n    // PURE thumbnail → colour-family fractions. Input: `d` = a flat RGBA byte array (Uint8ClampedArray in the\r\n    // browser via getImageData, a plain Buffer/Uint8Array offline) for a W×H image. Output: { family: fraction }\r\n    // over the counted item pixels, or null when there are no opaque item pixels. This is the DOM-free core the\r\n    // offline table generator extracts — do not reach for `document`, `Image`, OE, or GM in here.\r\n    function _pixHistFromData(d, W, H) {\r\n              const P = (x, y) => (y * W + x) * 4;\r\n              // ── BACKGROUND: transparent skipped by alpha; a SOLID opaque backdrop (Neopets bakes white behind\r\n              //    many items) is flood-filled from the EDGES so only edge-connected corner colour is dropped —\r\n              //    interior white (a white dress walled off by its own outline) is NOT edge-connected → survives.\r\n              const bg = new Uint8Array(W * H);\r\n              const seeds = [];\r\n              [[0, 0], [W - 1, 0], [0, H - 1], [W - 1, H - 1]].forEach(([cx, cy]) => { const p = P(cx, cy); if (d[p + 3] >= 128) seeds.push([d[p], d[p + 1], d[p + 2]]); });\r\n              const isBg = (p) => seeds.some(s => (Math.abs(d[p] - s[0]) + Math.abs(d[p + 1] - s[1]) + Math.abs(d[p + 2] - s[2])) < 50);\r\n              if (seeds.length) {\r\n                const stack = [];\r\n                const seed = (x, y) => { const q = y * W + x, p = P(x, y); if (!bg[q] && d[p + 3] >= 128 && isBg(p)) { bg[q] = 1; stack.push(x, y); } };\r\n                for (let x = 0; x < W; x++) { seed(x, 0); seed(x, H - 1); }\r\n                for (let y = 0; y < H; y++) { seed(0, y); seed(W - 1, y); }\r\n                while (stack.length) {\r\n                  const y = stack.pop(), x = stack.pop();\r\n                  if (x > 0) seed(x - 1, y); if (x < W - 1) seed(x + 1, y);\r\n                  if (y > 0) seed(x, y - 1); if (y < H - 1) seed(x, y + 1);\r\n                }\r\n                // ── FILL ENCLOSED BACKDROP HOLES: trapped pockets of the flat baked backdrop (walled off from the\r\n                //    edge by the item — the gaps in an open filigree headdress, the holes of a lattice) are never\r\n                //    reached by the edge flood-fill above, so they got counted as the item's white. Drop ANY opaque\r\n                //    pixel that NEAR-EXACTLY matches the corner backdrop colour, anywhere. Genuine item whites carry\r\n                //    shading/outlines so they miss this tight tolerance; the flat baked backdrop does not.\r\n                const isExactBg = (p) => seeds.some(s => (Math.abs(d[p] - s[0]) + Math.abs(d[p + 1] - s[1]) + Math.abs(d[p + 2] - s[2])) <= _PIX_BG_EXACT);\r\n                for (let i2 = 0; i2 < W * H; i2++) { if (bg[i2]) continue; const p = i2 * 4; if (d[p + 3] >= 128 && isExactBg(p)) bg[i2] = 1; }\r\n              }\r\n              // ── FLAT BACKDROP-WHITE (the frame / foreground / garland fix): when the item's art occupies the\r\n              //    CORNERS (a frame border, a foreground, a garland), the corner seeds are the DECORATION colour,\r\n              //    so the edge flood-fill never finds the white backdrop and the big ENCLOSED pet-hole — baked pure\r\n              //    #FFFFFF — got counted as the item's colour (every frame read \"mostly white\"). Drop any opaque\r\n              //    pixel that is near-pure-white AND locally FLAT (no shading/edge in its 4-neighbourhood): the baked\r\n              //    backdrop signature. A REAL white item is shaded (fails flatness) or cream/eggshell (fails\r\n              //    pure-white) so it survives — validated over the whole catalogue (~160 frames/foregrounds/garlands\r\n              //    de-white; genuine white items keep their white; zero items wrongly gain white).\r\n              for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {\r\n                const i = y * W + x, p = P(x, y);\r\n                if (bg[i] || d[p + 3] < 128) continue;\r\n                if (d[p] < _PIX_BGW_MIN || d[p + 1] < _PIX_BGW_MIN || d[p + 2] < _PIX_BGW_MIN) continue;   // not near-pure-white\r\n                let mx = 0;\r\n                if (x > 0)     { const q = P(x - 1, y); mx = Math.max(mx, Math.abs(d[p] - d[q]), Math.abs(d[p + 1] - d[q + 1]), Math.abs(d[p + 2] - d[q + 2])); }\r\n                if (x < W - 1) { const q = P(x + 1, y); mx = Math.max(mx, Math.abs(d[p] - d[q]), Math.abs(d[p + 1] - d[q + 1]), Math.abs(d[p + 2] - d[q + 2])); }\r\n                if (y > 0)     { const q = P(x, y - 1); mx = Math.max(mx, Math.abs(d[p] - d[q]), Math.abs(d[p + 1] - d[q + 1]), Math.abs(d[p + 2] - d[q + 2])); }\r\n                if (y < H - 1) { const q = P(x, y + 1); mx = Math.max(mx, Math.abs(d[p] - d[q]), Math.abs(d[p + 1] - d[q + 1]), Math.abs(d[p + 2] - d[q + 2])); }\r\n                if (mx <= _PIX_BGW_FLAT) bg[i] = 1;\r\n              }\r\n              // ── ITEM + DARK masks. item = opaque & not background. dark = an item pixel dark enough to be an\r\n              //    OUTLINE candidate (near-black). Dark pixels are NOT trusted until erosion proves they belong\r\n              //    to a SOLID dark fill (a black dress) rather than a 1–2px stroke around coloured art.\r\n              const item = new Uint8Array(W * H), dark = new Uint8Array(W * H);\r\n              for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {\r\n                const i = y * W + x, p = P(x, y);\r\n                if (d[p + 3] < 128 || bg[i]) continue;\r\n                item[i] = 1;\r\n                if ((Math.max(d[p], d[p + 1], d[p + 2]) + Math.min(d[p], d[p + 1], d[p + 2])) / 510 <= _PIX_DARK_L) dark[i] = 1;\r\n              }\r\n              // ── HALO REMOVAL: the anti-aliased ring where the item meets the WHITE backdrop is a BLEND of item\r\n              //    colour and background → light + desaturated → misclassified as white/grey. This is the real cause\r\n              //    of false \"white accents\" on wispy/feathered items (smoke, lace, thin silhouettes) — measured, not\r\n              //    trapped background. Peel item pixels that TOUCH the background AND read white/grey (a backdrop\r\n              //    blend). Chromatic edges stay (a purple edge is real); interior white stays (a white dress body is\r\n              //    surrounded by its own outline, never adjacent to bg). Iterated to catch a 2px halo.\r\n              for (let pass = 0; pass < _PIX_HALO_PASSES; pass++) {\r\n                const rm = [];\r\n                for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {\r\n                  const i = y * W + x; if (!item[i]) continue;\r\n                  if (!((x > 0 && bg[i - 1]) || (x < W - 1 && bg[i + 1]) || (y > 0 && bg[i - W]) || (y < H - 1 && bg[i + W]))) continue;  // not touching bg\r\n                  const p = P(x, y), f = _pixFamily(d[p], d[p + 1], d[p + 2]);\r\n                  if (f === 'white' || f === 'grey') rm.push(i);\r\n                }\r\n                if (!rm.length) break;\r\n                rm.forEach(i => { item[i] = 0; bg[i] = 1; });\r\n              }\r\n              // ── OUTLINE EROSION: a dark pixel counts as real BLACK only if its whole 3×3 neighbourhood is dark\r\n              //    (interior of a solid fill). A 1–2px outline has non-dark neighbours (the fill / background) →\r\n              //    it fails the test → it is treated as STRUCTURE and excluded from the colour count entirely.\r\n              //    (A big black fill loses only its 1px rim — negligible; a thin black strap is sacrificed too,\r\n              //    but is never a dominant/accent colour anyway. This is the fix for \"black border isn't black\".)\r\n              const solid = new Uint8Array(W * H);\r\n              for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {\r\n                const i = y * W + x; if (!dark[i]) continue;\r\n                let all = true;\r\n                for (let dy = -1; dy <= 1 && all; dy++) for (let dx = -1; dx <= 1; dx++) {\r\n                  const nx = x + dx, ny = y + dy;\r\n                  if (nx < 0 || ny < 0 || nx >= W || ny >= H || !dark[ny * W + nx]) { all = false; break; }\r\n                }\r\n                if (all) solid[i] = 1;\r\n              }\r\n              // ── COUNT by family over item pixels, skipping structural (eroded-away) dark pixels.\r\n              const cnt = {}; let op = 0;\r\n              for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {\r\n                const i = y * W + x; if (!item[i]) continue;\r\n                if (dark[i] && !solid[i]) continue;   // structural outline → not a colour\r\n                const p = P(x, y);\r\n                const f = _pixFamily(d[p], d[p + 1], d[p + 2]); if (!f) continue;\r\n                cnt[f] = (cnt[f] || 0) + 1; op++;\r\n              }\r\n              if (!op) return null;\r\n              const frac = {}; Object.keys(cnt).forEach(f => { frac[f] = cnt[f] / op; });\r\n              return frac;\r\n    }\r";
